// Expected behavior for key_share1, similar to key_share0:
// When engine_stable is high, slice j shall update or hold based on its qe.
property key_share1_update;
  @(posedge clk_i) disable iff (!rst_ni)
  (engine_stable) |->
    (!reg2hw.key_share1[0].qe && $past(engine_stable) |-> sw_key_data_reg[1][31:0] == $past(sw_key_data_reg[1][31:0]))
    &&
    (reg2hw.key_share1[0].qe |-> sw_key_data_reg[1][31:0] == reg2hw.key_share1[0].q);
endproperty
assert property (key_share1_update);

// Assume MaxKeyLen/32 = 4 for illustration; expand according to actual parameter
assert property (@(posedge clk_i) disable iff (!rst_ni)
  engine_stable |->
    (reg2hw.key_share1[0].qe || reg2hw.key_share1[1].qe ||
     reg2hw.key_share1[2].qe || reg2hw.key_share1[3].qe) == 0);
